type Page="oauth-consent"|"startup"|"login-entry"|"login"|"recognized-accounts"|"recognized-password"|"manage-profiles"|"profile-detail"|"find-account"|"reset-code"|"reset-password"|"device-verify"|"two-factor"|"register-welcome"|"register-identity"|"register-birthday"|"register-gender"|"register-phone"|"register-email"|"register-password"|"register-review"|"register-verify"|"customizing"|"home"|"policy"|"support-case"|"web-parity";
