 const validateIdentifier=(v:string)=>{const x=v.trim();if(!x)return"Enter your mobile number or email.";if(x.startsWith("+")&&!/^\+[1-9]\d{7,14}$/.test(x))return"Enter your mobile number with + and the country code.";if(/^\d+$/.test(x)&&(x.length<7||x.length>20))return"Enter a valid mobile number.";if(!/^\d+$/.test(x)&&!x.startsWith("+")&&!/^\S+@\S+\.\S+$/.test(x))return"Enter a valid mobile number or email address.";return null};
