 const submit=async()=>{if(busy)return;setErr("");const identifierError=validateIdentifier(id);if(identifierError){setErr(identifierError);return}const passwordError=validatePasswordWeb(pw);if(passwordError){setErr(passwordError);return}let identifier=id.trim();if(/^0\d+$/.test(identifier)&&network?.security?.callingCode)identifier="+"+String(network.security.callingCode).replace(/\D/g,"")+identifier.slice(1);await ensureWebDevice();if(/^\d+$/.test(id.trim())&&id.trim().startsWith("0")&&!identifier.startsWith("+")){setErr("We could not determine your country code from the startup network check. Enter your number with + and the country code.");return}setBusy(true);try{const r=await api<any>("/auth/login",{method:"POST",body:JSON.stringify({identifier,password:pw,platform:"web",deviceId:deviceId(),deviceType:"browser",deviceName:navigator.userAgent,browser:navigator.userAgent,loginSource:"web",appVersion:"web",networkIp:network?.security?.ip||undefined})});if(r.requiresVerification&&r.verification){sessionStorage.setItem("redom.login.challenge",JSON.stringify(r.verification));go("device-verify");return}if(r.requiresTwoFactor&&r.twoFactorVerification){sessionStorage.setItem("redom.login.2fa",JSON.stringify(r.twoFactorVerification));go("two-factor");return}if(r.success&&r.user&&r.session){saveSession(r.session);setUser({...r.user});go(afterLoginPage());return}const message=r.message||"Sign in could not be completed.";if(/pending verification/i.test(message)){try{const p=await api<any>("/auth/pending-registration/options",{method:"POST",body:JSON.stringify({identifier,password:pw})});setPendingMethods(p.methods||[]);setPendingOpen(true);return}catch{}}setErr(message)}catch(e){setErr(e instanceof Error?e.message:"Sign in failed.")}finally{setBusy(false)}};
