function DeviceVerify({go,setUser}:{go:(p:Page)=>void;setUser:(u:User|null)=>void}){const d=JSON.parse(sessionStorage.getItem("redom.login.challenge")||"null")||{},[code,setCode]=useState(""),[err,setErr]=useState(""),[busy,setBusy]=useState(false),sec=useTimer(d.expiresAt);const submit=async()=>{setBusy(true);setErr("");try{const r=await api<any>("/auth/verify-login-device",{method:"POST",body:JSON.stringify({challengeId:d.challengeId,code,deviceId:deviceId(),deviceName:navigator.userAgent,deviceType:"browser",platform:"web",loginSource:"web",appVersion:"web"})});if(r.requiresTwoFactor&&r.twoFactorVerification){sessionStorage.setItem("redom.login.2fa",JSON.stringify(r.twoFactorVerification));go("two-factor");return}if(r.success&&r.user&&r.session){saveSession(r.session);setUser({...r.user});go(afterLoginPage())}else setErr(r.message||"Verification failed.")}catch(e){setErr(e instanceof Error?e.message:"Verification failed.")}finally{setBusy(false)}};return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><div className="security-hero"><SvgAsset src={SecurityShieldSvg} className="auth-svg-icon" /></div><h1>Verify this browser</h1><p>Enter the 6-digit code sent to <b>{d.maskedTarget||"your account"}</b>.</p><div className="auth-form"><Field label="Verification code" value={code} onChange={v=>setCode(v.replace(/\D/g,"").slice(0,6))}/><ErrorBox text={err}/><Primary disabled={busy||code.length!==6||sec<=0} onClick={()=>void submit()}>{busy?"Verifying…":"Verify device"}</Primary><small className="auth-note">{sec>0?fmt(sec):"Code expired"}</small><button className="text-btn" onClick={()=>go("login")}>Back to login</button></div></Shell>}

function TwoFactor({go,setUser}:{go:(p:Page)=>void;setUser:(u:User|null)=>void}){const d=JSON.parse(sessionStorage.getItem("redom.login.2fa")||"null")||{},[code,setCode]=useState(""),[err,setErr]=useState(""),[busy,setBusy]=useState(false),sec=useTimer(d.expiresAt);const submit=async()=>{setBusy(true);setErr("");try{const r=await api<any>("/auth/verify-login-2fa",{method:"POST",body:JSON.stringify({challengeId:d.challengeId,code,deviceId:deviceId(),deviceName:navigator.userAgent,deviceType:"browser",platform:"web",loginSource:"web",appVersion:"web"})});if(r.success&&r.user&&r.session){saveSession(r.session);setUser({...r.user});go(routePage()==="support-case"?"support-case":"home")}else setErr(r.message||"Invalid verification code.")}catch(e){setErr(e instanceof Error?e.message:"Two-factor verification failed.")}finally{setBusy(false)}};return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><div className="security-hero"><SvgAsset src={LockedKeySvg} className="auth-svg-icon" /></div><h1>Two-factor authentication</h1><p>Enter the 6-digit code sent to <b>{d.maskedTarget||"your account"}</b>.</p><div className="auth-form"><Field label="6-digit code" value={code} onChange={v=>setCode(v.replace(/\D/g,"").slice(0,6))}/><ErrorBox text={err}/><Primary disabled={busy||code.length!==6||sec<=0} onClick={()=>void submit()}>{busy?"Verifying…":"Verify"}</Primary><small className="auth-note">{sec>0?fmt(sec):"Code expired"}</small><button className="text-btn" onClick={()=>go("login")}>Back to login</button></div></Shell>}

function PolicyPage(){const slug=decodeURIComponent(location.pathname.split("/").pop()||"");const[data,setData]=useState<any>(null),[err,setErr]=useState(""),[busy,setBusy]=useState(true);useEffect(()=>{let live=true;(async()=>{try{const r=await api<any>("/policies/"+encodeURIComponent(slug));if(!r.success)throw new Error(r.message||"Policy not found.");if(live)setData(r)}catch(e){if(live)setErr(e instanceof Error?e.message:"Unable to load this policy.")}finally{if(live)setBusy(false)}})();return()=>{live=false}},[slug]);if(busy)return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Loading policy…</h1></Shell>;if(err)return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Policy unavailable</h1><ErrorBox text={err}/><button className="text-btn" onClick={()=>location.href="/"}>Go to ReDom</button></Shell>;const d=data?.document||{};return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><span className="eyebrow">OFFICIAL REDOM POLICY</span><h1>{d.title||slug}</h1><p>{d.summary||""}</p><small className="auth-note">Version {data?.version||d.version||"current"} · Effective {data?.effectiveAt?new Date(data.effectiveAt).toLocaleDateString():d.effectiveAt?new Date(d.effectiveAt).toLocaleDateString():"current"}</small><div className="auth-form">{(d.sections||[]).map((s:any,i:number)=><section key={i}><h3>{s.heading}</h3><p>{s.body}</p></section>)}</div><button className="text-btn" onClick={()=>location.href="/"}>Back to ReDom</button></Shell>}

function SupportCasePage({go}:{go:(p:Page)=>void}){const caseNumber=(location.pathname.match(/R\d{11}$/i)?.[0]||"").toUpperCase();const[data,setData]=useState<any>(null),[err,setErr]=useState(""),[busy,setBusy]=useState(true);useEffect(()=>{let live=true;(async()=>{try{const r=await api<any>("/support/cases/"+encodeURIComponent(caseNumber));if(!r.success)throw new Error(r.message||"Support case not found.");if(live)setData(r)}catch(e){if(live)setErr(e instanceof Error?e.message:"Unable to load this support case.")}finally{if(live)setBusy(false)}})();return()=>{live=false}},[caseNumber]);if(busy)return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Loading your support case…</h1></Shell>;if(err)return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><h1>Support case unavailable</h1><ErrorBox text={err}/><p>This support link only opens a case owned by the ReDom account that signed in.</p><button className="text-btn" onClick={()=>go("home")}>Back to ReDom</button></Shell>;const messages=data.messages||[];return <Shell><div className="auth-brand"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b></div><span className="eyebrow">REDOM SUPPORT</span><h1>Case {data.case?.caseNumber||caseNumber}</h1><p>{data.case?.subject||"Your ReDom support case"}</p><small className="auth-note">Status: {data.case?.status||"unknown"}</small><div className="auth-form">{messages.map((m:any)=><div key={m.id} className="side-card"><b>{m.senderType==="ai"?"ReDom Support":m.senderType==="user"?"You":"ReDom"}</b><p>{m.body}</p><small>{m.createdAt?new Date(m.createdAt).toLocaleString():""}</small></div>)}</div><button className="text-btn" onClick={()=>go("home")}>Back to ReDom</button></Shell>}

function Home({user,setUser}:{user:User;setUser:(u:User|null)=>void}){const[posts,setPosts]=useState<any[]>([]),[stories,setStories]=useState<any[]>([]),[suggestions,setSuggestions]=useState<any[]>([]),[busy,setBusy]=useState(true),[err,setErr]=useState("");const load=async()=>{setBusy(true);try{const r=await api<any>("/feed/home?refresh="+Date.now());setPosts(r.posts||[]);setStories(r.friendStories||r.stories||[]);setSuggestions(r.suggestedProfiles||r.friendSuggestions||[]);setErr("")}catch(e){setErr(e instanceof Error?e.message:"Unable to load your Home Feed.")}finally{setBusy(false)}};useEffect(()=>{void load()},[]);const logout=async()=>{try{await api("/auth/logout",{method:"POST"})}catch{}clearSession();setUser(null)};return <div className="home-app"><header className="home-header"><button className="brand" onClick={()=>void load()}><SvgAsset src={ReDomMarkSvg} className="redom-mark-small" /><b>ReDom</b></button><span className="home-status">Live ReDom</span><button className="btn secondary" onClick={()=>{window.history.pushState({}, "", "/app/homeFeed"); window.location.reload();}}>Web screens</button><button className="btn secondary" onClick={()=>void logout()}>Log out</button></header><main className="home-main"><section className="feed-column"><div className="welcome-card"><Avatar user={user}/><div><b>Good to see you, {user.firstName}.</b><span>Your ReDom Home Feed</span></div><button className="btn secondary" onClick={()=>void load()}>Refresh</button></div><div className="story-strip"><div className="story-create"><div className="story-avatar"><SvgAsset src={ReDomMarkSvg} className="redom-mark-small" /></div><b>Create story</b><small>Story publishing is not exposed until its web flow is implemented.</small></div>{stories.slice(0,8).map((s:any)=><div className="story-item" key={s.id}><Avatar user={s} size={54}/><b>{s.firstName}</b></div>)}</div>{err?<ErrorBox text={err}/>:null}{busy?<div className="skeleton"><i/><i/><i/></div>:posts.length?posts.map((p:any)=><Post key={p.id} p={p}/>):<div className="empty"><SvgAsset src={HomeSvg} className="auth-svg-icon" /><h3>Your Home Feed is ready</h3><p>Posts from people, pages and recommendations will appear here.</p></div>}</section><aside className="home-side"><div className="side-card"><h3>People you may know</h3>{suggestions.slice(0,5).map((s:any)=><div className="person-row" key={s.userId}><Avatar user={s} size={40}/><div><b>{s.firstName} {s.lastName}</b><small>@{s.username}</small></div></div>)}</div><div className="side-card"><h3>Web development status</h3><p>The web app stops at the currently implemented Home Feed boundary. No unfinished navigation buttons are exposed.</p></div></aside></main></div>}
function Avatar({user,size=44}:{user:any;size?:number}){return user?.profilePhoto?<img className="avatar-img" src={user.profilePhoto} alt="" style={{width:size,height:size}}/>:<span className="avatar-fallback" style={{width:size,height:size}}>{String(user?.firstName||"R")[0].toUpperCase()}</span>}
function Post({p}:{p:any}){const[liked,setLiked]=useState(!!p.reactionSummary?.myReaction),[count,setCount]=useState(Number(p.reactionSummary?.total||0));const react=async()=>{try{const r=await api<any>("/feed/post-reaction",{method:"POST",body:JSON.stringify({postId:p.id,reactionType:liked?"":"like"})});setLiked(!liked);setCount(Number(r.total??r.reactionTotal??count+(liked?-1:1)))}catch{}};return <article className="web-post"><div className="post-head"><Avatar user={p} size={45}/><div><b>{p.firstName} {p.lastName}</b><small>@{p.username}</small></div></div>{p.content?<p className="post-content">{p.content}</p>:null}{p.media?.[0]?.objectKey?<img className="post-image" src={p.media[0].objectKey} alt=""/>:<div className="post-art"><SvgAsset src={ReDomMarkSvg} className="redom-mark-large" /></div>}<div className="post-meta"><span>{count} reactions</span></div><button className={liked?"post-like liked":"post-like"} onClick={()=>void react()}>♡ {liked?"Liked":"Like"}</button></article>}
// Web login entry intentionally resolves recognized browser accounts before the standard credential form.
function OAuthConsent({go}:{go:(p:Page)=>void}){const[request,setRequest]=useState<any>(null),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState("");const id=oauthRequestId();useEffect(()=>{let live=true;if(!id){go("login");return}void api<any>("/oauth/request/"+encodeURIComponent(id)).then(r=>{if(live)setRequest(r)}).catch(e=>{if(live)setError(e instanceof Error?e.message:"Unable to load the authorization request.")}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[id,go]);const approve=async()=>{if(!id||busy)return;setBusy(true);setError("");try{const r=await api<any>("/oauth/request/"+encodeURIComponent(id)+"/approve",{method:"POST"});if(!r.success||!r.code||!r.redirectUri)throw new Error(r.message||"Unable to approve access.");const u=new URL(r.redirectUri);u.searchParams.set("code",r.code);if(r.state)u.searchParams.set("state",r.state);window.location.assign(u.toString());}catch(e){setError(e instanceof Error?e.message:"Unable to approve access.");setBusy(false)}};if(loading)return <div className="recognized-web"><div className="recognized-loading">Loading authorization…</div></div>;return <div className="recognized-web"><main className="recognized-password" style={{maxWidth:520}}><img className="recognized-logo" src={ReDomLogoSvg} alt="ReDom"/><h1>Connect ReDom to ChatGPT</h1>{request?<><p>ChatGPT is requesting read-only access to your ReDom account.</p><ul style={{textAlign:"left",lineHeight:1.7}}><li>Account and profile information</li><li>Payment and transaction information</li><li>Login history and recognized devices</li><li>Account security status and location information</li></ul><p><b>Read only.</b> ChatGPT cannot change your ReDom account, payments, security settings, or credentials.</p><button type="button" className="recognized-login" disabled={busy} onClick={()=>void approve()}>{busy?"Connecting…":"Allow read-only access"}</button><button type="button" className="recognized-forgot" onClick={()=>window.history.back()}>Cancel</button>{error?<div className="recognized-error" role="alert">{error}</div>:null}</>:<div className="recognized-error" role="alert">{error||"Authorization request unavailable."}</div>}</main></div>;}

export default function App(){const[page,setPage]=useState<Page>(()=>{const routed=routePage();return routed==="policy"||routed==="support-case"||(routed==="login-entry"&&!oauthRequestId())?routed:oauthRequestId()&&routed==="login-entry"?"login":"startup"}),[network,setNetwork]=useState<NetworkProviderResponse|null>(null),[user,setUser]=useState<User|null>(null),[ready,setReady]=useState(false);const[loginEntryBusy,setLoginEntryBusy]=useState(false);const enterLogin=async()=>{if(loginEntryBusy)return;setLoginEntryBusy(true);try{await ensureWebDevice();const accounts=await getRecognizedWebAccounts();if(accounts.length){setPage("recognized-accounts");window.history.pushState({}, "", oauthRequestId()?`/app/login?oauth_request=${encodeURIComponent(oauthRequestId()!)}`:"/app/login");}else{setPage("login");window.history.pushState({}, "", oauthRequestId()?`/app/login?oauth_request=${encodeURIComponent(oauthRequestId()!)}`:"/app/login");}}catch{setPage("login");window.history.pushState({}, "", oauthRequestId()?`/app/login?oauth_request=${encodeURIComponent(oauthRequestId()!)}`:"/app/login");}finally{setLoginEntryBusy(false)}};const go=(p:Page)=>{const path=pagePath(p);if(path)window.history.pushState({}, "", path);setPage(p);window.scrollTo({top:0,behavior:"smooth"});};useEffect(()=>{const s=getSession();if(s){api<any>("/profile").then(r=>{if(r.profile){setUser({...r.profile,id:r.profile.userId});if(oauthRequestId())setPage("oauth-consent")}}).catch(()=>clearSession()).finally(()=>setReady(true))}else setReady(true)},[]);if(!ready)return <div className="boot"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b><span>Loading…</span></div>;if(page==="startup")return <Startup done={()=>{if(user){go("home");}else{void enterLogin();}}} setNetwork={setNetwork}/>;if(page==="oauth-consent")return <OAuthConsent go={go}/>;if(page==="login-entry")return <div className="recognized-web"><div className="recognized-loading">Loading login…</div></div>;if(page==="policy")return <PolicyPage/>;if(page==="support-case")return user?<SupportCasePage go={go}/>:<Login go={go} network={network} setUser={setUser}/>;if(page==="recognized-accounts")return <RecognizedAccounts go={go} network={network}/>;if(page==="recognized-password")return <RecognizedPassword go={go} setUser={setUser}/>;if(page==="manage-profiles")return <ManageProfiles go={go}/>;if(page==="profile-detail")return <ProfileDetail go={go}/>;if(page==="web-parity"||page==="home")return user?<WebParityRouter user={user} onLogout={async()=>{try{await api("/auth/logout",{method:"POST"})}catch{}clearSession();setUser(null);window.history.pushState({}, "", "/");setPage("startup");}}/>:<Login go={go} network={network} setUser={setUser}/>;if(page==="login")return <Login go={go} network={network} setUser={setUser}/>;if(page==="find-account")return <FindAccount go={go}/>;if(page==="reset-code")return <ResetCode go={go}/>;if(page==="reset-password")return <ResetPassword go={go}/>;if(page==="device-verify")return <DeviceVerify go={go} setUser={setUser}/>;if(page==="two-factor")return <TwoFactor go={go} setUser={setUser}/>;const f=readReg();if(page==="register-welcome")return <RegisterWelcome go={go}/>;if(!f)return <Login go={go} network={network} setUser={setUser}/>;if(page==="register-identity")return <RegIdentity flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-birthday")return <RegBirthday flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-gender")return <RegGender flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-phone")return <RegPhone flow={f!} go={go} setFlow={writeReg} network={network}/>;if(page==="register-email")return <RegEmail flow={f!} go={go} setFlow={writeReg} network={network}/>;if(page==="register-password")return <RegPassword flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-review")return <RegReview flow={f!} go={go} network={network}/>;if(page==="register-verify")return <RegVerify go={go}/>;if(page==="customizing")return <Customizing go={go} setUser={setUser}/>;return user?<Home user={user} setUser={setUser}/>:<Login go={go} network={network} setUser={setUser}/>}
